import { expect, test } from "../../fixtures";

test.describe("sign in", () => {
  test("requests without a session are rejected", { tag: "@AUTH-05" }, async ({ request }) => {
    // Act: no Authorization header and no session cookie
    const response = await request.get("/api/me", { headers: { Cookie: "" } });

    // Assert
    const body = await response.text();
    expect(response.status(), body).toBe(401);
    expect(JSON.parse(body).error.code, body).toBe("not_authenticated");
  });
});
